import { readFile, writeFile, mkdir } from "node:fs/promises"
import { existsSync } from "node:fs"
import path from "node:path"

const output = "docs/generated/web-inventory.md"
const source = await readFile("apps/web/src/App.tsx", "utf8")
const contract = JSON.parse(await readFile("apps/web/design-contract.json", "utf8"))
for (const item of [...contract.views, ...contract.actions]) {
  if (!source.includes(item.label)) throw new Error(`Web design label is missing from App.tsx: ${item.label}`)
}
const body = [
  "<!-- Generated by npm run docs:web. Do not edit. -->",
  "",
  "# Web design inventory",
  "",
  `Schema version: \`${contract.schemaVersion}\``,
  "",
  "## Views",
  "",
  "| ID | Label | Permission |",
  "|---|---|---|",
  ...contract.views.map(view => `| \`${view.id}\` | ${view.label} | \`${view.permission}\` |`),
  "",
  "## Actions",
  "",
  "| ID | Label | Endpoint | Permission | States |",
  "|---|---|---|---|---|",
  ...contract.actions.map(action => `| \`${action.id}\` | ${action.label} | \`${action.endpoint}\` | \`${action.permission}\` | ${action.states.map(state => `\`${state}\``).join(", ")} |`),
  "",
  "## Authentication",
  "",
  "| Mode | Identity source | Production |",
  "|---|---|---|",
  ...contract.authModes.map(mode => `| \`${mode.id}\` | ${mode.identitySource} | ${mode.production ? "yes" : "no"} |`),
  "",
  "## Realtime",
  "",
  `- Transport: ${contract.realtime.transport}`,
  `- Channel: ${contract.realtime.channel}`,
  `- Event: ${contract.realtime.event}`,
  ""
].join("\n")
if (process.argv.includes("--check")) {
  if (!existsSync(output) || await readFile(output,"utf8") !== body) throw new Error(`${output} is stale`)
} else {
  await mkdir(path.dirname(output), { recursive:true }); await writeFile(output,body)
}
